payload.text:
Aqui estão as alterações para adicionar o botão de resumo de comissões na tela principal.

Foi criado um novo componente modal para exibir o relatório e o botão foi adicionado ao cabeçalho da aplicação.

### Resumo das alterações:
1.  **`components/CommissionSummaryModal.tsx`**: Novo componente que calcula o total de comissões com base no histórico salvo e nas regras atuais.
2.  **`App.tsx`**: Adição do estado para controlar o modal e do botão "Minhas Comissões" no topo da tela.

# Updated files:

## components/CommissionSummaryModal.tsx

```tsx
import React, { useMemo } from 'react';
import { X, Coins, TrendingUp, DollarSign, Wallet } from 'lucide-react';
import { SavedCalculation, CommissionConfig } from '../types';
import { formatCurrency } from '../utils/currency';

interface CommissionSummaryModalProps {
  isOpen: boolean;
  onClose: () => void;
  history: SavedCalculation[];
  config: CommissionConfig;
}

const CommissionSummaryModal: React.FC<CommissionSummaryModalProps> = ({ 
  isOpen, 
  onClose, 
  history,
  config 
}) => {

  // Calcula o resumo com base no histórico e na configuração ATUAL
  const summary = useMemo(() => {
    let totalCommission = 0;
    let eligibleSales = 0;

    const details = history.map(item => {
      const profit = item.summary.profit;
      let commission = 0;

      // Se lucro for menor que o mínimo, sem comissão
      if (profit >= config.minProfitThreshold) {
        if (config.type === 'fixed' || config.type === 'mixed') {
          commission += config.fixedValue;
        }
        if (config.type === 'percent' || config.type === 'mixed') {
          const profitBase = profit > 0 ? profit : 0;
          commission += (profitBase * config.percentage) / 100;
        }
      }

      if (commission > 0) {
        totalCommission += commission;
        eligibleSales++;
      }

      return {
        ...item,
        commissionValue: commission
      };
    });

    return {
      total: totalCommission,
      count: eligibleSales,
      items: details
    };
  }, [history, config]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
      <div className="bg-zinc-900 border border-zinc-700 w-full max-w-lg rounded-xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="bg-zinc-800 p-4 flex justify-between items-center border-b border-zinc-700">
          <div className="flex items-center gap-2 text-amber-400">
            <Coins size={24} />
            <div>
              <h3 className="font-bold text-lg text-white">Minhas Comissões</h3>
              <p className="text-xs text-zinc-400">Resumo baseado no histórico salvo</p>
            </div>
          </div>
          <button onClick={onClose} className="text-zinc-400 hover:text-white transition-colors bg-zinc-700/50 p-2 rounded-full">
            <X size={20} />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 overflow-y-auto">

          {/* Cards de Resumo */}
          <div className="grid grid-cols-2 gap-4 mb-6">
            <div className="bg-green-900/20 border border-green-800 p-4 rounded-lg flex flex-col items-center justify-center text-center">
               <span className="text-green-400 mb-2"><Wallet size={28} /></span>
               <span className="text-sm text-zinc-400 uppercase font-bold">Total a Receber</span>
               <span className="text-2xl font-black text-white font-mono mt-1">
                 {formatCurrency(summary.total)}
               </span>
            </div>

            <div className="bg-blue-900/20 border border-blue-800 p-4 rounded-lg flex flex-col items-center justify-center text-center">
               <span className="text-blue-400 mb-2"><TrendingUp size={28} /></span>
               <span className="text-sm text-zinc-400 uppercase font-bold">Vendas Comissionadas</span>
               <span className="text-2xl font-black text-white font-mono mt-1">
                 {summary.count} <span className="text-sm font-normal text-zinc-500">/ {history.length}</span>
               </span>
            </div>
          </div>

          <div className="mb-2 flex items-center gap-2 text-xs text-zinc-500 bg-zinc-950 p-2 rounded border border-zinc-800">
            <DollarSign size={14} />
            Regra Atual: {config.type === 'fixed' ? 'Fixo' : config.type === 'percent' ? `${config.percentage}%` : 'Misto'} 
            {config.minProfitThreshold > 0 && ` (Min. Lucro: ${formatCurrency(config.minProfitThreshold)})`}
          </div>

          {/* Lista Detalhada */}
          <h4 className="text-xs font-bold text-zinc-400 uppercase mb-3 mt-6 border-b border-zinc-800 pb-2">
            Detalhamento (Últimos 5 salvos)
          </h4>

          <div className="space-y-2">
            {summary.items.length === 0 ? (
               <div className="text-center py-8 text-zinc-500 text-sm">
                 Nenhuma venda salva no histórico.
               </div>
            ) : (
              summary.items.map((item) => (
                <div key={item.id} className="flex justify-between items-center p-3 bg-zinc-950 rounded border border-zinc-800 hover:border-zinc-600 transition-colors">
                  <div className="flex flex-col">
                    <span className="font-bold text-white text-sm">
                      {item.data.licensePlate || 'SEM PLACA'}
                    </span>
                    <span className="text-[10px] text-zinc-500">{item.timestamp}</span>
                  </div>

                  <div className="text-right">
                    {item.commissionValue > 0 ? (
                      <div className="font-mono font-bold text-amber-400">
                        + {formatCurrency(item.commissionValue)}
                      </div>
                    ) : (
                      <div className="text-xs text-zinc-600 font-bold">
                        Não elegível
                      </div>
                    )}
                    <div className="text-[10px] text-zinc-500">
                      Lucro: {formatCurrency(item.summary.profit)}
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

        </div>
      </div>
    </div>
  );
};

export default CommissionSummaryModal;
```

## App.tsx

```tsx
import React, { useState, useMemo, useEffect } from 'react';
import { Calculator, RefreshCw, Sparkles, AlertTriangle, Building2, Save, History, ArrowRight, CarFront, Clock, AlertOctagon, Percent, Info, LogOut, ShieldCheck, FolderOpen, Coins, Wallet } from 'lucide-react';
import CurrencyInput from './components/CurrencyInput';
import TextInput from './components/TextInput';
import NumberInput from './components/NumberInput';
import SectionHeader from './components/SectionHeader';
import RateCalculatorModal from './components/RateCalculatorModal';
import FinancingSimulator from './components/FinancingSimulator';
import LoginScreen from './components/LoginScreen';
import AdminPanel from './components/AdminPanel';
import CommissionSummaryModal from './components/CommissionSummaryModal';
import { DealData, CalculationResult, SavedCalculation, BankType, User, UserRole, FieldVisibility, CommissionConfig } from './types';
import { formatCurrency, formatPercentage } from './utils/currency';
import { analyzeDeal } from './services/geminiService';
import { useBankCalculator } from './hooks/useBankCalculator';
import { userService } from './services/userService';
import { configService } from './services/configService';

// Helper para garantir um estado inicial limpo e novo (sem referências compartilhadas)
const getInitialData = (): DealData => ({
  licensePlate: '',
  fipeValue: 0, 
  stockDays: 0,
  invoiceValue: 0,
  vehicleCost: 0,
  bankReturn: 0,
  payments: {
    entry: 0,
    financing: 0,
    tradeIn: 0,
  },
  costs: {
    documentation: 0,
    accessories: 0,
    payoff: 0,
    debts: 0,
    others: 0,
  },
});

const App: React.FC = () => {
  // Inicializa usuários padrão se necessário
  useEffect(() => {
    userService.initialize();
  }, []);

  // --- Auth State ---
  const [user, setUser] = useState<User | null>(null);

  // --- Config State ---
  const [fieldConfig, setFieldConfig] = useState<FieldVisibility>(configService.getVisibility());
  const [commissionConfig, setCommissionConfig] = useState<CommissionConfig>(configService.getCommission());

  // --- App State ---
  const [data, setData] = useState<DealData>(getInitialData());

  // Hook customizado para lógica bancária - Iniciando com 'volks' conforme regra de negócio
  const { bankType, setBankType, getReturnAmount } = useBankCalculator('volks');

  const [analysis, setAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isRateModalOpen, setIsRateModalOpen] = useState(false);
  const [isAdminPanelOpen, setIsAdminPanelOpen] = useState(false);
  const [isCommissionModalOpen, setIsCommissionModalOpen] = useState(false);

  // Estado do Histórico
  const [history, setHistory] = useState<SavedCalculation[]>(() => {
    try {
      const saved = localStorage.getItem('dealHistory');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Erro ao carregar histórico", e);
      return [];
    }
  });

  // Atualiza config quando o painel admin salva
  const handleConfigUpdate = () => {
    setFieldConfig(configService.getVisibility());
    setCommissionConfig(configService.getCommission());
  };

  // --- Calculations ---
  const results: CalculationResult = useMemo(() => {
    const totalPayment = 
      data.payments.entry + 
      data.payments.financing + 
      data.payments.tradeIn;

    const totalCosts = 
      data.costs.documentation + 
      data.costs.accessories + 
      data.costs.payoff + 
      data.costs.debts + 
      data.costs.others;

    // Net revenue is what stays in the house before paying for the car itself
    const netRevenue = totalPayment - totalCosts;

    // Base Profit
    const profit = netRevenue - data.vehicleCost;

    // Margin based on Invoice Value
    const marginPercent = data.invoiceValue > 0 
      ? (profit / data.invoiceValue) * 100 
      : 0;

    // Profit with Bank Return (Bonus)
    const profitWithBank = profit + data.bankReturn;
    const marginPercentWithBank = data.invoiceValue > 0
      ? (profitWithBank / data.invoiceValue) * 100
      : 0;

    return {
      totalPayment,
      totalCosts,
      netRevenue,
      profit,
      marginPercent,
      profitWithBank,
      marginPercentWithBank,
    };
  }, [data]);

  // --- Commission Calculation ---
  const calculatedCommission = useMemo(() => {
    if (!commissionConfig.enabled) return 0;

    // Regra: Se o lucro operacional for menor que o mínimo, não paga comissão (ou paga 0)
    // Usamos o lucro operacional (results.profit) e não o bancário, geralmente.
    if (results.profit < commissionConfig.minProfitThreshold) return 0;

    let commission = 0;

    if (commissionConfig.type === 'fixed' || commissionConfig.type === 'mixed') {
      commission += commissionConfig.fixedValue;
    }

    if (commissionConfig.type === 'percent' || commissionConfig.type === 'mixed') {
      // Comissão sobre o lucro operacional
      // Se quiser sobre lucro com banco, mudaria para results.profitWithBank
      const profitBase = results.profit > 0 ? results.profit : 0; 
      commission += (profitBase * commissionConfig.percentage) / 100;
    }

    return commission;
  }, [results.profit, commissionConfig]);

  // --- Validação de Placa em Tempo Real ---
  const isPlateValid = useMemo(() => {
    const plate = data.licensePlate;
    if (!plate) return null;

    const clean = plate.replace(/[^A-Z0-9]/g, '');

    // Consideramos incompleto se tiver menos de 7 caracteres
    if (clean.length < 7) return null;

    // Regex para Padrão Antigo (AAA1234) e Mercosul (AAA1A23)
    // Antigo: 3 Letras + 4 Números
    // Mercosul: 3 Letras + 1 Número + 1 Letra + 2 Números
    const oldFormat = /^[A-Z]{3}\d{4}$/;
    const mercosulFormat = /^[A-Z]{3}\d[A-Z]\d{2}$/;

    return oldFormat.test(clean) || mercosulFormat.test(clean);
  }, [data.licensePlate]);

  // --- Helpers for Stock Age ---
  const getStockStatus = (days: number) => {
    // Garante que days seja tratado como número, mesmo se vier undefined de histórico antigo
    const safeDays = Number(days) || 0;
    if (safeDays >= 120) return { label: 'SUPER VELHO', color: 'bg-red-600', icon: <AlertOctagon size={16} className="animate-pulse" /> };
    if (safeDays >= 90) return { label: 'VELHO DE ESTOQUE', color: 'bg-amber-600', icon: <AlertTriangle size={16} /> };
    return { label: 'RECENTE', color: 'bg-green-600/50', icon: <Clock size={16} /> };
  };

  const stockStatus = getStockStatus(data.stockDays);

  // --- Handlers ---
  const handleLogin = (authenticatedUser: User) => {
    setUser(authenticatedUser);
  };

  const handleLogout = () => {
    setUser(null);
    handleResetNoConfirm(); // Limpa a tela ao sair
  };

  const updatePayment = (field: keyof typeof data.payments, value: number) => {
    setData(prev => {
      const newData = {
        ...prev,
        payments: { ...prev.payments, [field]: value }
      };

      // Se alterou o financiamento, recalcula o retorno bancário automaticamente usando o hook
      if (field === 'financing') {
        newData.bankReturn = getReturnAmount(value);
      }

      return newData;
    });
  };

  const handleBankTypeChange = (type: BankType) => {
    setBankType(type);
    // Recalcula o retorno passando o novo tipo explicitamente (pois o state do hook ainda não atualizou neste ciclo)
    setData(prev => ({
      ...prev,
      bankReturn: getReturnAmount(prev.payments.financing, type)
    }));
  };

  const updateCost = (field: keyof typeof data.costs, value: number) => {
    setData(prev => ({
      ...prev,
      costs: { ...prev.costs, [field]: value }
    }));
  };

  const handleAnalyze = async () => {
    if (!process.env.API_KEY) {
      setAnalysis("⚠️ Configure a API_KEY no ambiente para usar a inteligência artificial.");
      return;
    }
    setIsAnalyzing(true);
    setAnalysis(null);
    const result = await analyzeDeal(data, results);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const handleSave = () => {
    // Cria uma cópia profunda (Deep Copy) para evitar problemas de referência
    const dataSnapshot = JSON.parse(JSON.stringify(data));

    const newItem: SavedCalculation = {
      id: Date.now().toString(),
      timestamp: new Date().toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }),
      data: dataSnapshot,
      bankType,
      summary: {
        profit: results.profit,
        marginPercent: results.marginPercent
      }
    };

    const newHistory = [newItem, ...history].slice(0, 5); // Manter apenas os 5 últimos
    setHistory(newHistory);
    localStorage.setItem('dealHistory', JSON.stringify(newHistory));
  };

  // Função auxiliar interna sem confirmação
  const handleResetNoConfirm = () => {
    setData(getInitialData());
    setBankType('volks');
    setAnalysis(null);
  };

  const handleReset = () => {
    if (window.confirm('Tem certeza que deseja limpar todo o formulário?')) {
      handleResetNoConfirm();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const restoreCalculation = (item: SavedCalculation) => {
    // Reconstrói o objeto de dados garantindo que todos os campos numéricos sejam válidos
    // Isso previne erros se o histórico tiver dados antigos ou incompletos
    const restoredData: DealData = {
      licensePlate: item.data.licensePlate || '',
      stockDays: Number(item.data.stockDays) || 0,
      invoiceValue: Number(item.data.invoiceValue) || 0,
      vehicleCost: Number(item.data.vehicleCost) || 0,
      // Garante que o retorno bancário venha do salvo, não recalculado
      bankReturn: Number(item.data.bankReturn) || 0,
      fipeValue: 0, 
      payments: {
        entry: Number(item.data.payments?.entry) || 0,
        financing: Number(item.data.payments?.financing) || 0,
        tradeIn: Number(item.data.payments?.tradeIn) || 0,
      },
      costs: {
        documentation: Number(item.data.costs?.documentation) || 0,
        accessories: Number(item.data.costs?.accessories) || 0,
        payoff: Number(item.data.costs?.payoff) || 0,
        debts: Number(item.data.costs?.debts) || 0,
        others: Number(item.data.costs?.others) || 0,
      }
    };

    setBankType(item.bankType || 'volks');
    setData(restoredData);
    setAnalysis(null);

    // Feedback visual: rola para o topo para ver os dados preenchidos
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Se não estiver logado, exibe tela de login
  if (!user) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-zinc-950 p-4 md:p-8 font-sans text-white">
      {/* Modal de Cálculo de Taxa */}
      <RateCalculatorModal 
        isOpen={isRateModalOpen} 
        onClose={() => setIsRateModalOpen(false)}
        initialFinancedAmount={data.payments.financing}
      />

      {/* Painel de Admin */}
      <AdminPanel 
        isOpen={isAdminPanelOpen}
        onClose={() => setIsAdminPanelOpen(false)}
        currentUser={user}
        onConfigUpdate={handleConfigUpdate}
      />

      {/* Modal de Resumo de Comissões */}
      <CommissionSummaryModal
        isOpen={isCommissionModalOpen}
        onClose={() => setIsCommissionModalOpen(false)}
        history={history}
        config={commissionConfig}
      />

      <div className="max-w-6xl mx-auto">

        {/* Navbar com Info do Usuário */}
        <div className="bg-zinc-900 border-b border-zinc-800 -mx-4 -mt-8 px-8 py-3 mb-8 flex justify-between items-center shadow-lg">
           <div className="flex items-center gap-2">
             <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-black ${user.role === 'admin' ? 'bg-red-500' : 'bg-blue-500'}`}>
               {user.username.charAt(0).toUpperCase()}
             </div>
             <div className="flex flex-col">
               <span className="text-sm font-bold text-white leading-none">{user.name}</span>
               <span className="text-[10px] text-zinc-400 uppercase tracking-wider">{user.role === 'admin' ? 'Administrador' : 'Vendedor'}</span>
             </div>
           </div>

           <div className="flex items-center gap-4">
              {user.role === 'admin' && (
                <button 
                  onClick={() => setIsAdminPanelOpen(true)}
                  className="flex items-center gap-2 text-xs font-bold bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 px-3 py-1.5 rounded transition-colors text-red-400"
                >
                  <ShieldCheck size={14} />
                  PAINEL ADMIN
                </button>
              )}
              <div className="h-6 w-px bg-zinc-700"></div>
              <button 
                onClick={handleLogout}
                className="flex items-center gap-2 text-xs font-bold text-zinc-500 hover:text-white transition-colors"
              >
                <LogOut size={14} />
                SAIR
              </button>
           </div>
        </div>

        {/* Top Header */}
        <header className="flex flex-col md:flex-row md:justify-between md:items-center mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-black text-white flex items-center gap-2">
              <Calculator className="w-8 h-8 text-amber-400" />
              Calculadora de Margem
            </h1>
            <p className="text-zinc-400 mt-1">Ferramenta de estruturação de vendas de veículos</p>
          </div>
          <div className="flex gap-3 flex-wrap">
            {commissionConfig.enabled && (
              <button
                onClick={() => setIsCommissionModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-zinc-800 border border-amber-500/30 text-amber-400 rounded hover:bg-zinc-700 hover:border-amber-400 transition-all shadow-sm font-bold"
              >
                <Coins size={18} />
                Minhas Comissões
              </button>
            )}
            <button 
              onClick={handleReset}
              className="flex items-center gap-2 px-4 py-2 bg-zinc-800 border border-zinc-700 text-zinc-300 rounded hover:bg-zinc-700 transition-colors shadow-sm font-medium"
            >
              <RefreshCw size={18} />
              Limpar
            </button>
            <button 
              onClick={handleSave}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 border border-blue-500 text-white rounded hover:bg-blue-500 transition-colors shadow-sm font-bold"
            >
              <Save size={18} />
              Salvar
            </button>
            <button 
              onClick={handleAnalyze}
              disabled={isAnalyzing}
              className="flex items-center gap-2 px-4 py-2 bg-amber-400 text-black font-bold rounded shadow hover:bg-amber-500 transition-colors disabled:opacity-50"
            >
              <Sparkles size={18} />
              {isAnalyzing ? 'Analisando...' : 'Análise IA'}
            </button>
          </div>
        </header>

        {/* Top Inputs: Vehicle Data & Basics */}
        <div className="bg-zinc-900 p-6 rounded-lg shadow-sm border border-zinc-800 mb-6 relative overflow-hidden">
           {/* Status Stripe for Old Stock */}
           {data.stockDays >= 90 && (
              <div className={`absolute top-0 left-0 right-0 h-1 ${stockStatus.color}`}></div>
           )}

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {fieldConfig.licensePlate && (
                <div className="md:col-span-1 relative">
                  <TextInput 
                    label="Placa do Veículo" 
                    value={data.licensePlate || ''} 
                    onChange={(v) => setData(prev => ({...prev, licensePlate: v.toUpperCase()}))}
                    placeholder="ABC-1234"
                    maxLength={8}
                    isValid={isPlateValid}
                  />
                </div>
              )}

              {fieldConfig.stockDays && (
                <div className="md:col-span-1 relative">
                  <NumberInput
                    label="Dias de Estoque"
                    value={data.stockDays || 0}
                    onChange={(v) => setData(prev => ({...prev, stockDays: v}))}
                    placeholder="0"
                  />
                  {/* Badge de Status de Estoque */}
                  {(data.stockDays || 0) > 0 && (
                    <div className={`absolute -top-2 right-0 flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold text-white shadow-sm ${stockStatus.color} transition-colors`}>
                        {stockStatus.icon}
                        {stockStatus.label}
                    </div>
                  )}
                </div>
              )}

             {fieldConfig.invoiceValue && (
               <CurrencyInput 
                  label="Valor da Nota Fiscal" 
                  value={data.invoiceValue} 
                  onChange={(v) => setData(prev => ({...prev, invoiceValue: v}))}
                  className="md:col-span-1"
                />
             )}

             {fieldConfig.vehicleCost && (
                <CurrencyInput 
                  label="Custo do Veículo" 
                  value={data.vehicleCost} 
                  onChange={(v) => setData(prev => ({...prev, vehicleCost: v}))}
                  className="md:col-span-1"
                />
             )}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* LEFT COLUMN: Inputs */}
          <div className="lg:col-span-7 space-y-8">

            {/* Payment Form Section */}
            <section>
              <SectionHeader title="Forma de Pagamento" />
              <div className="bg-zinc-900 p-6 rounded-lg shadow-sm border border-zinc-800 space-y-4">
                {fieldConfig.entry && (
                  <CurrencyInput 
                    label="Entrada" 
                    value={data.payments.entry} 
                    onChange={(v) => updatePayment('entry', v)} 
                  />
                )}

                {fieldConfig.financing && (
                  <div className="grid grid-cols-1 sm:grid-cols-12 gap-4 items-end">
                    <div className="sm:col-span-7 relative">
                      <CurrencyInput 
                        label="Financiamento" 
                        value={data.payments.financing} 
                        onChange={(v) => updatePayment('financing', v)} 
                      />
                      {/* Botão de atalho para calculadora de taxa */}
                      <button 
                        onClick={() => setIsRateModalOpen(true)}
                        className="absolute top-0 right-0 text-[10px] font-bold bg-amber-500/10 text-amber-400 border border-amber-500/30 px-2 py-0.5 rounded hover:bg-amber-500/20 transition-colors flex items-center gap-1"
                        title="Calcular taxa de juros deste financiamento"
                      >
                        <Percent size={10} /> Calc. Taxa
                      </button>
                    </div>
                    <div className="sm:col-span-5 flex flex-col">
                      <label className="text-xs font-bold text-zinc-400 uppercase tracking-wider mb-1 flex items-center gap-1">
                        <Building2 size={14} /> Instituição
                      </label>
                      <select 
                        value={bankType}
                        onChange={(e) => handleBankTypeChange(e.target.value as BankType)}
                        className="w-full h-[42px] border border-zinc-700 bg-zinc-800 rounded px-3 text-white focus:outline-none focus:ring-2 focus:ring-amber-400"
